const {chromium}=require('playwright');const F='file://'+process.argv[2];const S=process.argv[3];
const ok=(c,m)=>console.log((c?'PASS ':'FAIL ')+m);
(async()=>{const b=await chromium.launch();const p=await b.newPage({viewport:{width:1440,height:900}});const e=[];p.on('pageerror',x=>e.push(x.message));
await p.goto(F);await p.evaluate(()=>localStorage.clear());await p.reload();await p.waitForTimeout(400);
ok(await p.locator('.lp-hero textarea').count()===0,'hero has no chat box');
ok(await p.locator('main .composer').count()===0,'no chat box anywhere on the landing page');
await p.screenshot({path:S+'/v2-fold.png'});
for(const btn of await p.locator('[data-gfix]').all()) await btn.click();
ok(!(await p.locator('#gapready').isHidden()),'fixing all gaps shows ready to agree');
await p.click('[data-role="growth"]');ok((await p.textContent('#rq')).includes('baseline'),'role switch shows that role\'s questions');
await p.click('#ropts .opt >> nth=1');await p.waitForTimeout(500);ok((await p.textContent('#rstep'))==='2 / 2','answering advances');
await p.click('#nfbtn');ok(await p.locator('#numfix.fixed').count()===1,'number fix applies placeholders');
await p.click('.seg [data-stage="learn"]');ok(await p.locator('.spanel[data-panel="learn"]').isVisible(),'stage tabs switch');
await p.click('.faq summary >> nth=1');ok(await p.locator('.faq details[open]').count()===1,'faq opens');
await p.screenshot({path:S+'/v2-full.png',fullPage:true});
console.log('page height',await p.evaluate(()=>document.body.scrollHeight));
await p.evaluate(()=>scrollTo(0,0));await p.click('.lp-hero [data-act="new"]');
ok(await p.locator('.newchat h1').count()===1,'Start free opens the new-chat screen');
await p.screenshot({path:S+'/v2-new.png'});
await p.click('form[data-form="start"] [data-fill="reorder"]');await p.click('form[data-form="start"] .send');await p.waitForSelector('.m-ai .pcard',{timeout:15000});
ok(await p.locator('.m-user').count()===1,'sending starts the chat');
await p.click('[data-act="home"]');await p.waitForTimeout(300);ok(await p.locator('.lp-hero').count()===1,'logo returns to the landing page');
await p.click('.lp-hero ~ section [data-try="carts"], [data-try="carts"]');await p.waitForSelector('.m-ai .pcard');
ok((await p.textContent('.m-user')).includes('save a cart'),'"See it in the chat" starts the matching example');
const m=await b.newPage({viewport:{width:390,height:844}});await m.goto(F);await m.waitForTimeout(500);
ok(!(await m.evaluate(()=>document.documentElement.scrollWidth>innerWidth)),'landing fits a phone');
await m.click('.lp-hero [data-act="new"]');ok(!(await m.evaluate(()=>document.documentElement.scrollWidth>innerWidth)),'new chat fits a phone');
ok(e.length===0,'no errors '+e.join('; '));await b.close();})();
